			/*
			 * "닫기" 버튼(btnClose)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnCloseClick(e){
			    var btnClose = e.control;
			    app.close();
			}

			/*
			 * "업무보고서 등록" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e){
			    var btnSave = e.control;
			    
			    // Validation Check
			    var validate = checkValidation();
			    if (validate.result == false) {
			        util.Msg.alert(app, validate.message);
			        return false;
			    }
			    
			    var deptCd = app.getAppProperty("deptCd");
			    
			    var txtSelectedDate = "";
			    if (deptCd == "324" || deptCd == "325") {    // 사이버상담
			        txtSelectedDate = app.lookup("opt78").value;
			    } else {  // 모바일상담
			        txtSelectedDate = app.lookup("opt20").value;
			        
			        // 모바일상담 출근시간 데이터 설정
			        var dsMobileReport = app.lookup("dsMobileReport");
			        
			        var inWorkYmd = dsMobileReport.getValue(0, "IN_WORK_YMD");
			        var inWorkHh = dsMobileReport.getValue(0, "IN_WORK_HH");
			        var inWorkMm = dsMobileReport.getValue(0, "IN_WORK_MM");
			        
			        var chttAtendbDt = toFmtString("%s %s:%s:00", inWorkYmd, inWorkHh, inWorkMm);
			        console.log("chttAtendbDt: " + chttAtendbDt);
			        
			        app.lookup("dsCmmnReport").setValue(0, "CHTT_ATENDB_DT", chttAtendbDt);
			        
			        // 시간외근무신청 관련 데이터 설정
			        var dsOvtimeMobile = app.lookup("dsOvtimeMobile");
			        var overTimeYn = app.getAppProperty("overTimeYn");
			        console.log("overTimeYn: " + overTimeYn);
			        dsOvtimeMobile.setValue(0, "OVTIME_APLY_YN", overTimeYn);
			        
			        if (overTimeYn == "Y") {
			            var inOvrTimeYmd = dsOvtimeMobile.getValue(0, "IN_OVRTIME_YMD");
			            var inOvrTimeHh = dsOvtimeMobile.getValue(0, "IN_OVRTIME_HH");
			            var inOvrTimeMm = dsOvtimeMobile.getValue(0, "IN_OVRTIME_MM");
			            
			            if (ValueUtil.fixNull(inOvrTimeYmd) != "") {
			                 var overTimeWorkDt = toFmtString("%s %s:%s:00", inOvrTimeYmd, inOvrTimeHh, inOvrTimeMm);
			                 console.log("overTimeWorkDt: " + overTimeWorkDt);
			                 dsOvtimeMobile.setValue(0, "OVTIME_WORK_DT", overTimeWorkDt);
			            } else {
			                dsOvtimeMobile.setValue(0, "OVTIME_WORK_DT", "");
			            }
			        } else {
			            dsOvtimeMobile.setValue(0, "OVTIME_WORK_DT", "");
			        }
			        
			        console.log("dsOvtimeMobile : ", dsOvtimeMobile.getRowDataRanged());
			    }
			    
			    // 등록데이터 (공통) 디버깅
			    console.log("dsCmmnReport : ", app.lookup("dsCmmnReport").getRowDataRanged());
			    
			    var msg = txtSelectedDate + "\n해당 근무시간으로 업무 보고서를 등록 하시겠습니까?";
			    
			    util.Msg.confirm(app, msg, null, function() {
			        if (deptCd == "326") {
			            var vcFile = app.lookup('cmnsinglefileupload1');    // 시작시간첨부파일
			            if (vcFile.isFileModified()) {
			                vcFile.send(function() {
			                    var vcFile2 = app.lookup('cmnsinglefileupload2');   // 종료시간첨부파일
			                    if (vcFile2.isFileModified()) {
			                        vcFile2.send(function() {
			                            doSave();        
			                        });
			                    } else {
			                        doSave();
			                    }
			                });
			            } else {
			                doSave();
			            }
			        } else {
			            doSave();
			        }
			    });
			}

			/**
			 * Validation 체크
			 * 
			 */
			function checkValidation() {
			    // validation object 초기화
			    var retObj = {
			        result: true,
			        message: "정상적으로 처리되었습니다."
			    };
			    
			    var dmReport = app.lookup('dmReport');
			    
			    var chttEvlYn = dmReport.getValue("CHTT_EVL_YN");
			    var ntardEvlYn = dmReport.getValue("NTABRD_EVL_YN");
			    
			    // 채팅평가여부에 대한 체크 (근무배정표_인큐베이팅)
			    if (chttEvlYn == "Y") {
			        var dsChatEvlInfo = app.lookup("dsChatEvlInfo");
			        // CHRO_NO : 채팅방번호
			        var chroNoVal = dsChatEvlInfo.getValue(0, "CHRO_NO");
			        
			        // 채팅상담내역선택 체크
			        if (ValueUtil.isNull(chroNoVal)) {
			            retObj.result = false;
			            retObj.message = "채팅내역을 선택해주세요.";
			            return retObj;
			        }
			        
			        // RVSN_CHTT_DSCSN_EVL_SCORE1 : 개정채팅상담평가점수1 (호소문제파악)
			        // RVSN_CHTT_DSCSN_EVL_SCORE2 : 개정채팅상담평가점수2 (상담목표설정)
			        // RVSN_CHTT_DSCSN_EVL_SCORE3 : 개정채팅상담평가점수3 (접촉유지)
			        // RVSN_CHTT_DSCSN_EVL_SCORE4 : 개정채팅상담평가점수4 (설명력)
			        // RVSN_CHTT_DSCSN_EVL_SCORE5 : 개정채팅상담평가점수5 (대안제시)
			        // RVSN_CHTT_DSCSN_EVL_SCORE6 : 개정채팅상담평가점수6 (기관정보제공)
			        // RVSN_CHTT_DSCSN_EVL_SCORE7 : 개정채팅상담평가점수7 (공감표현)
			        // RVSN_CHTT_DSCSN_EVL_SCORE8 : 개정채팅상담평가점수8 (마무리)
			        // CHTT_OVERAL_RELEVA_SCORE : 채팅전반적적절성점수 (전반적적절성)
			        
			        var chatDscsnEvlScore1Val = dsChatEvlInfo.getValue(0, "RVSN_CHTT_DSCSN_EVL_SCORE1");
			        var chatDscsnEvlScore2Val = dsChatEvlInfo.getValue(0, "RVSN_CHTT_DSCSN_EVL_SCORE2");
			        var chatDscsnEvlScore3Val = dsChatEvlInfo.getValue(0, "RVSN_CHTT_DSCSN_EVL_SCORE3");
			        var chatDscsnEvlScore4Val = dsChatEvlInfo.getValue(0, "RVSN_CHTT_DSCSN_EVL_SCORE4");
			        var chatDscsnEvlScore5Val = dsChatEvlInfo.getValue(0, "RVSN_CHTT_DSCSN_EVL_SCORE5");
			        var chatDscsnEvlScore6Val = dsChatEvlInfo.getValue(0, "RVSN_CHTT_DSCSN_EVL_SCORE6");
			        var chatDscsnEvlScore7Val = dsChatEvlInfo.getValue(0, "RVSN_CHTT_DSCSN_EVL_SCORE7");
			        var chatDscsnEvlScore8Val = dsChatEvlInfo.getValue(0, "RVSN_CHTT_DSCSN_EVL_SCORE8");
			        var chttOveralRelevaScoreVal = dsChatEvlInfo.getValue(0, "CHTT_OVERAL_RELEVA_SCORE");
			        
			        // 채팅상담 평가입력 체크
			        if (ValueUtil.isNull(chatDscsnEvlScore1Val) || ValueUtil.isNull(chatDscsnEvlScore2Val)
			                || ValueUtil.isNull(chatDscsnEvlScore3Val) || ValueUtil.isNull(chatDscsnEvlScore4Val)
			                || ValueUtil.isNull(chatDscsnEvlScore5Val) || ValueUtil.isNull(chatDscsnEvlScore6Val)
			                || ValueUtil.isNull(chatDscsnEvlScore7Val) || ValueUtil.isNull(chatDscsnEvlScore8Val)
			                || ValueUtil.isNull(chttOveralRelevaScoreVal) 
			        ) {
			            retObj.result = false;
			            retObj.message = "채팅상담 평가항목을 모두 입력해주세요!!";
			            return retObj;
			        }
			    }
			    
			    // 게시판평가여부에 대한 체크 (근무배정표_인큐베이팅)
			    if (ntardEvlYn == "Y") {
			        var dsNtabrdEvlInfo = app.lookup("dsNtabrdEvlInfo");
			        // BBSCTT_ESNTAL_NO : 게시글고유번호 / RETE_ESNTAL_NO : 답글고유번호
			        var bbsCttEsntalNoVal = dsNtabrdEvlInfo.getValue(0, "BBSCTT_ESNTAL_NO");
			        var reteEsntalNoVal = dsNtabrdEvlInfo.getValue(0, "RETE_ESNTAL_NO");
			        
			        // 게시판상담내역선택 체크
			        if (ValueUtil.isNull(bbsCttEsntalNoVal)) {
			            retObj.result = false;
			            retObj.message = "게시판상담내역을 선택해주세요.";
			            return retObj;
			        }
			        
			        // RVSN_NTABRD_DSCSN_EVL_SCORE1 : 개정게시판상담평가점수1 (호소문제파악)
			        // RVSN_NTABRD_DSCSN_EVL_SCORE2 : 개정게시판상담평가점수2 (목표설정)
			        // RVSN_NTABRD_DSCSN_EVL_SCORE3 : 개정게시판상담평가점수3 (설명력)
			        // RVSN_NTABRD_DSCSN_EVL_SCORE4 : 개정게시판상담평가점수4 (공감표현)
			        // RVSN_NTABRD_DSCSN_EVL_SCORE5 : 개정게시판상담평가점수5 (대안제시)
			        // RVSN_NTABRD_DSCSN_EVL_SCORE6 : 개정게시판상담평가점수6 (기관정보제공)
			        // RVSN_NTABRD_DSCSN_EVL_SCORE7 : 개정게시판상담평가점수7 (마무리)
			        // NTABRD_OVERAL_RELEVA_SCORE : 게시판전반적적절성점수 (전반적적절성)
			        
			        var ntardDscsnEvlScore1Val = dsNtabrdEvlInfo.getValue(0, "RVSN_NTABRD_DSCSN_EVL_SCORE1");
			        var ntardDscsnEvlScore2Val = dsNtabrdEvlInfo.getValue(0, "RVSN_NTABRD_DSCSN_EVL_SCORE2");
			        var ntardDscsnEvlScore3Val = dsNtabrdEvlInfo.getValue(0, "RVSN_NTABRD_DSCSN_EVL_SCORE3");
			        var ntardDscsnEvlScore4Val = dsNtabrdEvlInfo.getValue(0, "RVSN_NTABRD_DSCSN_EVL_SCORE4");
			        var ntardDscsnEvlScore5Val = dsNtabrdEvlInfo.getValue(0, "RVSN_NTABRD_DSCSN_EVL_SCORE5");
			        var ntardDscsnEvlScore6Val = dsNtabrdEvlInfo.getValue(0, "RVSN_NTABRD_DSCSN_EVL_SCORE6");
			        var ntardDscsnEvlScore7Val = dsNtabrdEvlInfo.getValue(0, "RVSN_NTABRD_DSCSN_EVL_SCORE7");
			        var ntardOveralRelevaScoreVal = dsNtabrdEvlInfo.getValue(0, "NTABRD_OVERAL_RELEVA_SCORE");
			        
			        // 게시판상담 평가입력 체크
			        if (ValueUtil.isNull(ntardDscsnEvlScore1Val) || ValueUtil.isNull(ntardDscsnEvlScore2Val)
			                || ValueUtil.isNull(ntardDscsnEvlScore3Val) || ValueUtil.isNull(ntardDscsnEvlScore4Val)
			                || ValueUtil.isNull(ntardDscsnEvlScore5Val) || ValueUtil.isNull(ntardDscsnEvlScore6Val)
			                || ValueUtil.isNull(ntardDscsnEvlScore7Val) || ValueUtil.isNull(ntardOveralRelevaScoreVal)
			        ) {
			            retObj.result = false;
			            retObj.message = "게시판상담 평가항목을 모두 입력해주세요!!";
			            return retObj;
			        }
			    }
			    
			    return retObj;
			}

